'use strict';
// Scratch verification of contract paths; not part of the test suite.
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));

function deferred() {
  let resolve, reject;
  const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
  return { promise, resolve, reject };
}

async function main() {
  // 1. Invalidated flight must not commit or detach a newer flight.
  {
    const g1 = deferred(), g2 = deferred();
    let calls = 0;
    const c = createCache({ now: () => 0, ttlMs: 100, load: () => (++calls === 1 ? g1.promise : g2.promise) });
    const r1 = c.get('k');
    await tick();
    c.invalidate('k');
    const r2 = c.get('k'); // fresh flight
    const r3 = c.get('k'); // joins fresh flight (dedup)
    g1.resolve('old');
    await r1; // obsolete flight settles
    assert.equal(calls, 2, 'no extra load after obsolete settle');
    g2.resolve('new');
    assert.equal(await r2, 'new');
    assert.equal(await r3, 'new');
    assert.equal(await c.get('k'), 'new'); // committed, cached
    assert.equal(calls, 2);
  }

  // 2. Rejected loads are never cached; subsequent get retries.
  {
    let calls = 0;
    const c = createCache({ now: () => 0, ttlMs: 100, load: () => (++calls === 1 ? Promise.reject('boom') : 'ok') });
    await assert.rejects(c.get('k'), r => r === 'boom');
    await assert.rejects(c.get('k'), r => r === 'boom'); // same settled rejection? No: retry
    // After the first rejection settles, a later get must retry:
    await tick();
    assert.equal(await c.get('k'), 'ok');
    assert.ok(calls >= 2, 'retried after rejection');
  }

  // 3. Synchronous throw is not cached; retry works.
  {
    let calls = 0;
    const c = createCache({ now: () => 0, ttlMs: 100, load: () => { calls += 1; if (calls === 1) throw new Error('sync'); return 'fine'; } });
    await assert.rejects(c.get('k'), /sync/);
    await tick();
    assert.equal(await c.get('k'), 'fine');
    assert.equal(calls, 2);
  }

  // 4. set() wins over earlier loads; old completion must not overwrite or restart TTL.
  {
    const g = deferred();
    let t = 0;
    const c = createCache({ now: () => t, ttlMs: 100, load: () => g.promise });
    const r = c.get('k');
    await tick();
    c.set('k', 'manual');
    g.resolve('loaded');
    assert.equal(await r, 'loaded'); // original waiter still gets its value
    assert.equal(await c.get('k'), 'manual');
    t = 50; // within manual TTL (set at t=0); if old load restarted TTL at settle, still fine here
    assert.equal(await c.get('k'), 'manual');
    t = 150; // expired relative to set-time deadline; must start new load, not detached one
    let calls2 = 0;
    const c2 = createCache({ now: () => t, ttlMs: 100, load: () => { calls2 += 1; return 'L' + calls2; } });
    assert.equal(await c2.get('k'), 'L1');
  }

  // 5. set value expiring while old load pending: get starts a NEW load, not the detached one.
  {
    const g = deferred();
    let t = 0;
    let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => (++calls === 1 ? g.promise : 'fresh' + calls) });
    const r = c.get('k');
    await tick();
    c.set('k', 'manual');
    t = 20; // manual value expired; old load still pending
    const r2 = c.get('k');
    g.resolve('old');
    assert.equal(await r, 'old');
    assert.equal(await r2, 'fresh2');
    assert.equal(calls, 2);
  }

  // 6. Concurrent dedup + TTL starts at commit; ttlMs=0 dedups unsettled flight only.
  {
    const g = deferred();
    let t = 0, calls = 0;
    const c = createCache({ now: () => t, ttlMs: 0, load: () => { calls += 1; return g.promise; } });
    const r1 = c.get('k');
    const r2 = c.get('k');
    g.resolve('v');
    assert.equal(await r1, 'v');
    assert.equal(await r2, 'v');
    assert.equal(calls, 1, 'unsettled flight deduped with ttlMs=0');
    const r3 = c.get('k'); // settled value never reused
    g.resolve('v2');
    assert.equal(await r3, 'v2');
    assert.equal(calls, 2);
  }

  // 7. clear() barrier; load calling invalidate synchronously on itself.
  {
    let calls = 0;
    const c = createCache({ now: () => 0, ttlMs: 100, load: key => { calls += 1; if (calls === 1) c.invalidate(key); return 'v' + calls; } });
    assert.equal(await c.get('k'), 'v1');
    assert.equal(c.size, 0, 'self-invalidated load not stored');
    assert.equal(await c.get('k'), 'v2');
    assert.equal(c.size, 1);
    c.clear();
    assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'v3');
  }

  // 8. size counts unexpired values only; reading size discards expired without detaching flights.
  {
    const g = deferred();
    let t = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => g.promise });
    c.set('a', 1);
    const r = c.get('b');
    t = 20;
    assert.equal(c.size, 0, 'expired discarded, flight not counted');
    g.resolve('B');
    assert.equal(await r, 'B');
    assert.equal(c.size, 1, 'flight committed after expiry check');
  }

  console.log('scratch: all contract checks passed');
}

main().catch(err => { console.error(err); process.exit(1); });

