'use strict';

// A detached flight still settles its original callers. The registry tracks
// only flights available for subsequent readers of each key.
function createFlights() {
  const pending = new Map();

  return {
    run(key, work, commit) {
      if (pending.has(key)) return pending.get(key);
      const promise = Promise.resolve().then(work).then(
        value => {
          // A detached (obsolete) flight still settles its own waiters but
          // must not store its value or unregister a newer flight.
          if (pending.get(key) === promise) {
            pending.delete(key);
            commit(value);
          }
          return value;
        },
        reason => {
          // Rejections are never cached; unregister so a later get retries.
          if (pending.get(key) === promise) {
            pending.delete(key);
          }
          throw reason;
        }
      );
      pending.set(key, promise);
      return promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

module.exports = { createFlights };
